    if len(appointment_dates) < 2:
        return 0.0

    date_objects = [datetime.strptime(date_str, "%Y-%m-%d") for date_str in appointment_dates]
    date_diffs = [(date_objects[i] - date_objects[i-1]).days for i in range(1, len(date_objects))]
    avg_days = sum(date_diffs) / (len(date_diffs))

    return round(avg_days, 2)

def manage_events(events, today):
    from datetime import datetime

    upcoming_events = []
    today_date = datetime.strptime(today, '%Y-%m-%d').date()

    for event in events:
        event_date = datetime.strptime(event['date'], '%Y-%m-%d').date()
        if event_date >= today_date:
            upcoming_events.append(event)

    upcoming_events.sort(key=lambda x: datetime.strptime(x['date'], '%Y-%m-%d'))

    return upcoming_events

