def find_next_appointment(appointments, duration):
    start_time = "09:00"
    end_time = "17:00"

    appointments = sorted([convert_to_minutes(time) for time in appointments])
    new_appointment_end = duration

    current_time = convert_to_minutes(start_time)

    for appointment in appointments:
        if appointment - current_time >= new_appointment_end:
            return convert_to_time(current_time)
        else:
            current_time = appointment + 1

    if convert_to_minutes(end_time) - current_time >= new_appointment_end:
        return convert_to_time(current_time)
    else:
        return "No available slot"

