from datetime import datetime

def calculate_avg_session_duration(sessions):
    user_sessions = {}

    for session in sessions:
        user_id = session["user_id"]
        start_time = datetime.strptime(session["session_start"], "%Y-%m-%d %H:%M:%S")
        end_time = datetime.strptime(session["session_end"], "%Y-%m-%d %H:%M:%S")
        duration = (end_time - start_time).total_seconds()

        if user_id in user_sessions:
            user_sessions[user_id].append(duration)
        else:
            user_sessions[user_id] = [duration]

    avg_durations = {}
    for user_id, durations in user_sessions.items():
        avg_duration = sum(durations) / len(durations)
        avg_durations[user_id] = avg_duration

    return avg_durations
```

