def calculate_molecular_weight(molecular_formula):
    atomic_weights = {
        'H': 1.008,
        'C': 12.011,
        'N': 14.007,
        'O': 15.999
    }

    total_weight = 0.0
    current_element = ''
    current_count = 0

    for char in molecular_formula:
        if char.isalpha():
            if current_count > 0:
                total_weight += atomic_weights[current_element] * current_count
                current_count = 0
            current_element = char
        else:
            current_count = current_count * 10 + int(char)

    if current_count > 0:
        total_weight += atomic_weights[current_element] * current_count

    return total_weight

