def encrypt_message(message, key):
    # Create a dictionary to map each letter to its position in the key
    letter_map = {letter: index for index, letter in enumerate(key)}

    # Initialize an empty string to store the encrypted message
    encrypted_message = ""

    # Iterate over each character in the message
    for char in message:
        # If the character is a lowercase letter
        if char.isalpha() and char.islower():
            # Replace it with the corresponding letter from the key
            encrypted_message += key[letter_map[char]]
        else:
            # Otherwise, keep the character unchanged
            encrypted_message += char

    return encrypted_message

