    historical_keywords = ["empire", "civilization", "dynasty", "revolution", "artifact"]

    text = text.lower()
    philosophical_count = sum(text.count(" " + keyword + " ") for keyword in philosophical_keywords)
    historical_count = sum(text.count(" " + keyword + " ") for keyword in historical_keywords)

    if philosophical_count > historical_count:
        return "Philosophy"
    elif historical_count > philosophical_count:
        return "History"
    else:
        return "Equal"

