def can_partition_strings(strings):
    total_chars = sum(len(s) for s in strings)
    if total_chars % 2 != 0:
        return False

    target_sum = total_chars // 2
    dp = [False] * (target_sum + 1)
    dp[0] = True

    for s in strings:
        n = len(s)
        for j in range(target_sum, n - 1, -1):
            dp[j] = dp[j] or dp[j - n]

    return dp[target_sum]

