def find_most_popular_book(book_list):
    book_counts = {}

    # Count the occurrences of each book
    for book in book_list:
        if book in book_counts:
            book_counts[book] += 1
        else:
            book_counts[book] = 1

    # Find the book(s) with the highest count
    max_count = max(book_counts.values())
    popular_books = [book for book, count in book_counts.items() if count == max_count]

    # Return one of the popular books
    return popular_books[0]

