    for title, year in film_projects:
        initials = ''.join(word[0].upper() for word in title.split())
        year_str = str(year)
        key = initials + year_str

        if key not in sequence_map:
            sequence_map[key] = 1
        else:
            sequence_map[key] += 1

        sequence_num = str(sequence_map[key]).zfill(3)
        code = initials + year_str + sequence_num
        codes.append(code)

