def calculate_min_viewings(episodes, n):
    total_minutes = n * 60
    episode_durations = []
    total_duration = 0
    viewings = 0

    for duration in episodes:
        episode_durations.append(duration)

    while total_duration < total_minutes:
        for duration in episode_durations:
            total_duration += duration
            if total_duration >= total_minutes:
                break
        viewings += 1

    return viewings

