    year1, month1, day1 = map(int, date1.split('-'))
    year2, month2, day2 = map(int, date2.split('-'))

    # Handle BC years
    if year1 < 0:
        year1 = abs(year1) + 1
    else:
        year1 = -(year1 - 1)

    if year2 < 0:
        year2 = abs(year2) + 1
    else:
        year2 = -(year2 - 1)

    # Calculate the number of years between the two dates
    years_diff = abs(year1 - year2)

    return years_diff

