def check_grammar(sentence, verbs, nouns):
    # Check if the sentence starts with a capital letter
    if not sentence[0].isupper():
        return False

    # Check if the sentence ends with a period, question mark, or exclamation mark
    if sentence[-1] not in ['.', '?', '!']:
        return False

    # Check if each word is separated by a single space
    words = sentence.split()
    for i in range(len(words) - 1):
        if words[i][-1] != ' ' or words[i + 1][0] != words[i + 1][0].isalnum():
            return False

    # Check if the sentence contains at least one verb and one noun
    has_verb = False
    has_noun = False
    for word in words:
        if word in verbs:
            has_verb = True
        elif word in nouns:
            has_noun = True

    if not has_verb or not has_noun:
        return False

    return True

